#define SUBDIVS 40.0
#define DENSITY 0.6
#define ANIM_AMP 0.9

// Utility Methods

float rand(vec2 v) {
 return fract(sin(dot(v, vec2(12.345, 67.890)))*123456.0);
}

vec2 rand2(vec2 v) {
 return vec2(rand(v), rand(v+12.345));
}

// Debug Tools

float border(vec2 v, float thickness) {
    return (v.x <= thickness ? 1.0 : 0.0)
         + (v.y <= thickness ? 1.0 : 0.0);
}

float point(vec2 v, float radius) {
    return length(v) <= radius ? 1.0 : 0.0;
}

// Foam

vec2 randomPointInCell(vec2 cell) {
    vec2 rt = rand2(cell);
    vec2 anim = (vec2(sin(iTime*rt.x), sin(iTime*rt.y))+1.0)/2.0;
    anim = (anim*ANIM_AMP)+(1.0-ANIM_AMP)/2.0;
    return (cell + anim)/SUBDIVS;
}

float edge(vec2 uv, vec2 rand_pt, vec2 cell) {
    if (rand(cell) > DENSITY) {
        return 0.0;
    }

    vec2 point = randomPointInCell(cell);

    vec2 dir_cell = point - rand_pt;
    vec2 dir_uv = uv - rand_pt;

    float proj_l = dot(dir_uv, dir_cell)/(length(dir_cell)*length(dir_cell));

    if (proj_l < 0.0) return 0.0;
    vec2 proj = rand_pt + dir_cell*proj_l;

    float d = clamp(0.002/length(uv-proj),0.1,1.0)-0.1;
    float edge = d/10.0;

    return edge;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.y;

    // Rotate by 45 degrees, it looks better this way
    uv = mat2(0.7071, 0.7071,
             -0.7071, 0.7071)*uv;

    // Split space into a grid
    vec2 uv_floor = floor(uv*SUBDIVS);
    vec2 uv_fract = fract(uv*SUBDIVS);
    float grid = 0.0; //border(uv_fract, 0.02); // used for debug

    // Generate random point on grid (for display only)
    vec2 rand_pt = randomPointInCell(uv_floor);
    float pt = 0.0; //point(uv-rand_pt, 0.005); // used for debug

    float v = 0.0;
    if (rand(uv_floor) <= DENSITY) {
        // Draw edges to surrounding boxes
        float acc = 0.0;  
        vec2 cell = vec2(uv_floor.x+1.0,uv_floor.y);
        acc += edge(uv, rand_pt, cell);
        cell = vec2(uv_floor.x-1.0,uv_floor.y);
        acc += edge(uv, rand_pt, cell);
        cell = vec2(uv_floor.x,uv_floor.y+1.0);
        acc += edge(uv, rand_pt, cell);
        cell = vec2(uv_floor.x,uv_floor.y-1.0);
        acc += edge(uv, rand_pt, cell);
        v = 8.0*acc;    
    }

    // Output to screen

    fragColor = vec4(pt+v,v,grid+v,1.0);
}
